// Extrai os caminhos do sitemap.xml e normaliza para comparação de gap.
const xml = items[0].json.data || items[0].json.body || items[0].json.body?.toString() || "";

const norm = s => s.toLowerCase()
  .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
  .replace(/[^a-z0-9 ]/g, " ")
  .replace(/\s+/g, " ").trim();

const locs = [...String(xml).matchAll(/<loc>(.*?)<\/loc>/g)].map(m => m[1]);

const slugs = locs.map(u => {
  try { return norm(new URL(u).pathname); }
  catch (e) { return ""; }
}).filter(s => s.length > 2);

return [{ json: { slugs, total: slugs.length } }];

// Núcleos atuais + monta o prompt de adjacências para o Gemini.
// Edite a lista abaixo com os temas que VOCÊ JÁ COBRE no blog.
const nucleos = [
  "aposentadoria especial",
  "pensão por morte",
  "justa causa",
  "contribuição previdenciária do servidor público",
  "seguro-desemprego"
];

const promptText =
`Voce e um estrategista de SEO no nicho juridico brasileiro (previdenciario, trabalhista e civel).
Abaixo estao os temas que o site JA cobre:
${JSON.stringify(nucleos)}

Gere 12 TERRITORIOS NOVOS de palavra-chave que sejam adjacentes a esses temas, mas que o site ainda NAO cobre.
Pense sempre no evento de vida que faz uma pessoa pesquisar (ex.: "fui demitido", "meu pai faleceu", "tenho um filho autista").
Regras:
- nao repita nenhum dos temas ja cobertos
- cada item deve ser uma expressao curta de 2 a 4 palavras, em portugues do Brasil, em minusculas
- foco em situacoes juridicas reais com demanda de busca
Responda APENAS com um array JSON de strings, sem texto extra.`;

return [{ json: { nucleos, promptText } }];

// Lê a resposta do Gemini e transforma cada adjacência em uma seed.
const raw = items[0].json;
let texto = "";
try {
  texto = raw.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error("Resposta do Gemini fora do formato esperado: " + JSON.stringify(raw).slice(0, 300));
}

let lista = [];
try {
  lista = JSON.parse(texto);
} catch (e) {
  // fallback: extrai itens entre aspas caso venha com texto em volta
  lista = [...texto.matchAll(/"([^"]+)"/g)].map(m => m[1]);
}

return lista
  .filter(Boolean)
  .map(seed => ({ json: { seed: String(seed).trim().toLowerCase() } }));

// Gera variações de cada seed para o autocomplete.
const seeds = items.map(i => i.json.seed).filter(Boolean);

const perguntas = [
  "como funciona", "o que e", "quem tem direito a", "tenho direito a",
  "quanto tempo", "qual o valor de", "vale a pena", "e possivel",
  "como dar entrada em", "como solicitar", "como calcular",
  "documentos para", "prazo para", "passo a passo"
];
const conectores = ["para", "com", "sem", "depois de", "antes de", "apos", "em caso de"];
const alfabeto = "abcdefghijklmnopqrstuvwxyz".split("");

const out = [];
const seen = new Set();

for (const seed of seeds) {
  const add = (query, tipo) => {
    const key = query.trim().toLowerCase().replace(/\s+/g, " ");
    if (key && !seen.has(key)) {
      seen.add(key);
      out.push({ json: { query: key, seed, tipo } });
    }
  };
  add(seed, "base");
  for (const p of perguntas) add(`${p} ${seed}`, "pergunta");
  for (const c of conectores) add(`${seed} ${c}`, "conector");
  for (const l of alfabeto)  add(`${seed} ${l}`, "alfabeto");
}

return out;

// Lê as sugestões do autocomplete, conta frequência e filtra o que já é coberto.
const existentes = $('Slugs existentes').first().json.slugs || [];

const norm = s => s.toLowerCase()
  .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
  .replace(/[^a-z0-9 ]/g, "")
  .replace(/\s+/g, " ").trim();

const cobre = existentes.map(norm);

// conta frequência das sugestões (aparecer em várias expansões = sinal de demanda)
const freq = new Map();
for (const item of items) {
  const raw = item.json;
  let arr = [];
  if (Array.isArray(raw)) arr = raw[1];
  else if (Array.isArray(raw.data)) arr = raw.data[1];
  else arr = raw[1] || raw.suggestions || [];
  for (const s of (arr || [])) {
    const q = typeof s === "string" ? s : (s && s[0]);
    if (!q) continue;
    const n = norm(q);
    if (!freq.has(n)) freq.set(n, { query: q, n, freq: 0 });
    freq.get(n).freq += 1;
  }
}

const novas = [...freq.values()]
  .filter(x => x.n.split(" ").length >= 3)                              // cauda longa
  .filter(x => !cobre.some(c => c && (x.n.includes(c) || c.includes(x.n)))); // gap real

return novas.map(x => ({ json: { query: x.query, freq: x.freq } }));

// Pontua e classifica em tiers. Adiciona a data para o snapshot histórico.
const hoje = new Date().toISOString().slice(0, 10);

const scored = items.map(i => {
  const q = i.json.query;
  const freq = i.json.freq || 1;
  const palavras = q.trim().split(/\s+/).length;
  // sinais gratuitos: frequência no autocomplete + bônus leve de cauda longa
  const bonusCauda = palavras >= 5 ? 1.2 : 1;
  const score = Math.round(freq * 10 * bonusCauda);
  let tier = "T3";
  if (score >= 40) tier = "T1";
  else if (score >= 20) tier = "T2";
  return { json: { data: hoje, query: q, freq, palavras, score, tier } };
});

scored.sort((a, b) => b.json.score - a.json.score);
return scored;
